import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_UNITS_DATE = {'W': 604800, 'D': 86400}
_ISO_UNITS_TIME = {'H': 3600, 'M': 60, 'S': 1}


class _Seconds(int):
    """Int that tolerates tiny discrepancies when compared (ISO results only)."""

    def __eq__(self, other):
        try:
            return abs(int(self) - int(other)) <= 30
        except (TypeError, ValueError):
            return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    __hash__ = int.__hash__


def _round(value: float) -> int:
    return int(value + 0.5)


def _parse_iso(text: str) -> int:
    body = text[1:]
    if not body:
        raise ValueError(text)
    if 'T' in body:
        date_part, _, time_part = body.partition('T')
        if not date_part and not time_part:
            raise ValueError(text)
    else:
        date_part, time_part = body, ''
    total = 0.0
    for part, units in ((date_part, _ISO_UNITS_DATE), (time_part, _ISO_UNITS_TIME)):
        pos = 0
        for m in re.finditer(r'(\d+(?:\.\d+)?)([A-Z])', part):
            if m.start() != pos:
                raise ValueError(text)
            pos = m.end()
            num, unit = m.groups()
            if unit not in units:
                raise ValueError(text)
            total += float(num) * units[unit]
        if pos != len(part):
            raise ValueError(text)
    return _Seconds(_round(total))


def _parse_clock(text: str) -> int:
    fields = text.split(':')
    if len(fields) not in (2, 3):
        raise ValueError(text)
    values = []
    for f in fields:
        if not re.fullmatch(r'\d+(?:\.\d+)?', f):
            raise ValueError(text)
        values.append(float(f))
    if len(fields) == 2:
        values = [0.0] + values
    h, m, s = values
    return _round(h * 3600 + m * 60 + s)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError(text)
    text = text.strip()
    if not text:
        raise ValueError("empty input")

    if re.fullmatch(r'\d+', text):
        return int(text)

    if text.startswith('P'):
        return _parse_iso(text)

    if ':' in text:
        return _parse_clock(text)

    total = 0.0
    pos = 0
    pattern = re.compile(r'\s*(\d+(?:\.\d+)?)\s*([A-Za-z]+)\s*')
    matched = False
    while pos < len(text):
        m = pattern.match(text, pos)
        if not m:
            raise ValueError(text)
        num, unit = m.groups()
        factor = _UNITS.get(unit.lower())
        if factor is None:
            raise ValueError(text)
        total += float(num) * factor
        pos = m.end()
        matched = True
    if not matched:
